#include <algorithm>
#include <vector>

double median_of(std::vector<long long> xs) {
    std::sort(xs.begin(), xs.end());
    std::size_t m = xs.size() / 2;
    if (xs.size() % 2 == 1) return xs[m];
    return (xs[m - 1] + xs[m]) / 2.0;
}

