#include <cstdio>
#include <vector>

// Hidden and ready: CallPayoff, binomial_price, time_us, median_of.
std::vector<double> tree_table(const std::vector<int>& ns, int batch) {
    CallPayoff call(100);
    std::vector<double> prices;
    double sink = 0;  // every timed price is added here
    for (int n : ns) {
        // 1. warm-up: price once and keep the price
        double price = binomial_price(call, 100, 0.05, 0.2, 1, n, false);
        // 2. time 5 batches of `batch` trees into runs
        std::vector<long long> runs;
        for (int rep = 0; rep < 5; ++rep)
            runs.push_back(time_us([&] {
                for (int b = 0; b < batch; ++b)
                    sink += binomial_price(call, 100, 0.05, 0.2, 1, n, false);
            }));
        // 3. print n, the price and the median time per tree
        std::printf("n = %4d  price %.4f  %8.1f us per tree\n", n, price, median_of(runs) / batch);
        prices.push_back(price);
    }
    std::printf("(sink %.1f)\n", sink);
    return prices;
}

widget.prelude:
#include <chrono>
#include <algorithm>
#include <cmath>
#include <vector>

struct Payoff {
    virtual ~Payoff() = default;
    virtual double operator()(double s) const = 0;
};

struct CallPayoff : Payoff {
    double k;
    explicit CallPayoff(double k) : k(k) {}
    double operator()(double s) const override { return std::max(s - k, 0.0); }
};

struct PutPayoff : Payoff {
    double k;
    explicit PutPayoff(double k) : k(k) {}
    double operator()(double s) const override { return std::max(k - s, 0.0); }
};

long long zq_trees = 0;

// Level 2's pricer: one row of n + 1 values, reused at every step.
double binomial_price(const Payoff& payoff, double s, double r, double sigma,
                      double t, int n, bool american) {
    ++zq_trees;
    double dt = t / n;
    double u = std::exp(sigma * std::sqrt(dt)), d = 1 / u;
    double growth = std::exp(r * dt);
    double q = (growth - d) / (u - d), disc = 1 / growth;
    std::vector<double> v(n + 1);
    for (int j = 0; j <= n; ++j)
        v[j] = payoff(s * std::pow(u, j) * std::pow(d, n - j));
    for (int i = n - 1; i >= 0; --i)
        for (int j = 0; j <= i; ++j) {
            v[j] = disc * (q * v[j + 1] + (1 - q) * v[j]);
            if (american)
                v[j] = std::max(v[j], payoff(s * std::pow(u, j) * std::pow(d, i - j)));
        }
    return v[0];
}

long long zq_timed = 0;

template <class F>
long long time_us(F f) {
    ++zq_timed;
    auto start = std::chrono::steady_clock::now();
    f();
    auto stop = std::chrono::steady_clock::now();
    return std::chrono::duration_cast<std::chrono::microseconds>(stop - start).count();
}

